USE ev_charging_db;
SET FOREIGN_KEY_CHECKS=0;
UPDATE users SET username = 'aarav.sharma' WHERE user_id = 5;
UPDATE chargers SET status = 'OCCUPIED' WHERE charger_id IN (SELECT charger_id FROM (SELECT charger_id FROM charging_sessions WHERE status = 'ACTIVE') t);
SELECT ch.station_id, DATE(cs.start_time), HOUR(cs.start_time), COUNT(*), COALESCE(SUM(cs.energy_kwh), 0)
FROM charging_sessions cs JOIN chargers ch ON ch.charger_id = cs.charger_id WHERE cs.status = 'COMPLETED'
GROUP BY ch.station_id, DATE(cs.start_time), HOUR(cs.start_time);
SET FOREIGN_KEY_CHECKS=1;
